// 比較相手: 得意ジャンルの重なりが多い順 → 比較できる料金項目が多い順 → データ順で自分の次から巡回
// （同順位のときにどのページも同じ相手にならないようにするため）。自分は除く
export function comparePeers(slug: string, max = 4): Partner[] {
  const selfIdx = PARTNERS.findIndex((p) => p.slug === slug);
  if (selfIdx < 0) return [];
  const self = PARTNERS[selfIdx];
  const n = PARTNERS.length;
  const filled = (s: string) => Object.keys(KEY_PRICES[s] ?? {}).length;
  return PARTNERS.map((p, i) => ({ p, i: (i - selfIdx + n) % n, shared: p.tags.filter((t) => self.tags.includes(t)).length }))
    .filter((x) => x.p.slug !== slug && x.shared > 0 && filled(x.p.slug) > 0)
    .sort((a, b) => b.shared - a.shared || filled(b.p.slug) - filled(a.p.slug) || a.i - b.i)
    .slice(0, max)
    .map((x) => x.p);
}

export function partnersByTag(tag: ServiceTag): Partner[] {
  return PARTNERS.filter((p) => p.tags.includes(tag));
}
